import numpy as np

def pass_at_k(n, c, k):
    # n samples drawn, c of them correct
    if n - c < k:
        return 1.0
    return 1.0 - np.prod(1.0 - k / np.arange(n - c + 1, n + 1))

pass_at_k(10, 3, 2)

def generate_with_budget(prompt, min_tokens, max_tokens):
    trace = []
    while True:
        tok = model.next_token(prompt, trace)
        if tok == END_OF_THINKING:
            if len(trace) < min_tokens:
                trace += tokenize("Wait")   # suppress stop
                continue
            break
        trace.append(tok)
        if len(trace) >= max_tokens:
            break                         # force stop
    trace += [END_OF_THINKING] + tokenize("Final Answer:")
    return model.generate_answer(prompt, trace)
